"""Compact full-area viewer: compressed vector payload, same analyzed values."""
from pathlib import Path
import json,gzip,base64,shutil
import geopandas as gpd
from shapely import normalize
from carto_basemap import tiles_url,ATTR
ROOT=Path(__file__).resolve().parents[1];OUT=ROOT/'output/geoai_full_scope'

def main():
 blocks=gpd.read_file(OUT/'ai_block_environment.gpkg').to_crs(26914)
 blocks=blocks[['GEOID20','ai_canopy_cover_pct','provisional_walking_friction_heat_0_100','landsat_summer_surface_temp_c','landsat_mean_valid_dates','ai_imagery_coverage_01','representative_address','geometry']].rename(columns={'GEOID20':'id','ai_canopy_cover_pct':'cover','provisional_walking_friction_heat_0_100':'friction','landsat_summer_surface_temp_c':'heat','landsat_mean_valid_dates':'observations','ai_imagery_coverage_01':'coverage','representative_address':'address'})
 blocks.geometry=blocks.geometry.simplify(3,preserve_topology=True)
 edges=gpd.read_file(OUT/'ai_walking_edges.gpkg').to_crs(26914)
 edges=edges.loc[~edges.geometry.map(lambda g:normalize(g).wkb_hex).duplicated(),['ai_tree_cover_01','ai_corridor_coverage_01','geometry']].rename(columns={'ai_tree_cover_01':'tree_fraction','ai_corridor_coverage_01':'coverage'})
 edges.geometry=edges.geometry.simplify(.6,preserve_topology=True)
 scope=gpd.read_file(ROOT/'output/four_zip_walking_network/zip_boundaries.geojson').to_crs(26914)
 points_ll=scope.geometry.representative_point().to_crs(4326)
 scope['lat']=points_ll.y;scope['lon']=points_ll.x
 routes=gpd.read_file(OUT/'full_scope_routes.gpkg').to_crs(4326)
 points=gpd.read_file(OUT/'illustrative_endpoints.geojson')
 def packed(gdf):return base64.b64encode(gzip.compress(gdf.to_crs(4326).to_json(drop_id=True).encode(),compresslevel=9)).decode()
 blocks_payload=packed(blocks);paths_payload=packed(edges);routes_payload=packed(routes);points_payload=packed(points);scope_payload=packed(scope)
 template='''<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>EmPath full-area GeoAI</title><link rel="stylesheet" href="https://unpkg.com/leaflet@1.9.4/dist/leaflet.css"><style>html,body,#map{height:100%;margin:0;font:13px Arial}#map{min-height:600px}.info{background:white;padding:11px;max-width:320px;line-height:1.45;border-radius:5px;box-shadow:0 1px 5px #999}select{display:block;width:100%;margin:6px 0;padding:5px}.scale{height:12px;margin:5px 0}.swatch{display:inline-block;width:22px;height:5px;margin-right:7px;vertical-align:middle}</style></head><body><div id="map"></div><script src="https://unpkg.com/leaflet@1.9.4/dist/leaflet.js"></script><script>
const map=L.map('map',{scrollWheelZoom:false});L.tileLayer(TILE_URL,{attribution:ATTRIBUTION,maxZoom:19}).addTo(map);
const esc=x=>String(x??'Unknown').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const number=v=>v===null||v===undefined?'Unknown':Number(v).toFixed(1);
const colors=['#d95f0e','#fec44f','#a1d99b','#41ab5d','#006d2c'];
const bins=[0,.1,.25,.5,.75,1.000001],labels=['0–10%','10–25%','25–50%','50–75%','75–100%'];
function treeColor(v){if(v===null||!Number.isFinite(v))return '#999';let i=0;while(i<4&&v>=bins[i+1])i++;return colors[i];}
function ramp(value,mode){if(value===null||!Number.isFinite(value))return '#ccc';if(mode==='heat')value=Math.max(0,Math.min(100,100*(value-HEAT_MIN)/(HEAT_MAX-HEAT_MIN))); const ends=mode==='cover'?['#ffffcc','#006837']:['#ffffcc','#800026'];let a=ends.map(c=>[1,3,5].map(i=>parseInt(c.slice(i,i+2),16)));return '#'+a[0].map((x,i)=>Math.round(x+(a[1][i]-x)*value/100).toString(16).padStart(2,'0')).join('');}
let mode='paths',blockLayer,pathLayer,pathData,routeData,routeOutline,routeLayer,routeMode='Hide routes';
const control=L.control({position:'topright'});control.onAdd=()=>{const d=L.DomUtil.create('div','info');d.innerHTML='<b>Full four-ZIP GeoAI analysis</b><select id="theme"><option value="heat">Landsat summer surface temperature (°C)</option><option value="cover">AI tree cover — census blocks</option><option value="friction">Provisional walking friction — census blocks</option><option value="paths">Walking paths — tree adjacency</option></select><label>Illustrative route objective</label><select id="objective"><option>Tree-adjacency priority</option><option>Distance–canopy trade-off</option><option>Shortest distance</option><option>Hide routes</option></select><small>Four endpoint pairs, not verified entrances.<br>Tree priority: best mean adjacency among up to 30 diverse candidates within 1.5× shortest distance.</small>';L.DomEvent.disableClickPropagation(d);return d;};control.addTo(map);
const legend=L.control({position:'bottomright'});legend.onAdd=()=>{const d=L.DomUtil.create('div','info');d.id='legend';return d;};legend.addTo(map);
function updateLegend(){document.getElementById('legend').innerHTML=(mode==='heat'?'<b>Landsat summer 2025 surface temperature</b><div class="scale" style="background:linear-gradient(to right,#ffffcc,#800026)"></div>HEAT_RANGE °C<br>Clear-sky observations around noon.<br>Not air temperature or daily maximum.':mode==='paths'?'<b>Predicted tree adjacency</b><br>Tree-covered pixels in 5 m path corridor':mode==='cover'?'<b>Predicted tree cover by block</b><div class="scale" style="background:linear-gradient(to right,#ffffcc,#006837)"></div>0% → 100%': '<b>Provisional walking friction</b><div class="scale" style="background:linear-gradient(to right,#ffffcc,#800026)"></div>0 → 100; higher = more friction<br>Equal weights: temperature + traffic + canopy deficit')+'<hr><b>Route/path color: nearby predicted trees</b>'+colors.map((c,i)=>'<div><span class="swatch" style="background:'+c+'"></span>'+labels[i]+'</div>').join('')+'<small>Orange = least adjacent; dark green = most.<br>Gray = unknown. Not measured shade.<br>100% imagery coverage ≠ validated accuracy.</small>';}
async function unpack(encoded){const bytes=Uint8Array.from(atob(encoded),c=>c.charCodeAt(0));const s=new Blob([bytes]).stream().pipeThrough(new DecompressionStream('gzip'));return JSON.parse(await new Response(s).text());}
function blockStyle(f){return {color:'#666',weight:.3,fillColor:ramp(f.properties[mode==='paths'?'cover':mode],mode==='paths'?'cover':mode),fillOpacity:mode==='paths'?0:.78};}
function drawRoute(){if(routeOutline)map.removeLayer(routeOutline);if(routeLayer)map.removeLayer(routeLayer);if(!routeData||routeMode==='Hide routes')return;const selected={type:'FeatureCollection',features:routeData.features.filter(f=>f.properties.route===routeMode)};const dash=routeMode==='Shortest distance'?'8 6':routeMode==='Distance–canopy trade-off'?'2 6':null;routeOutline=L.geoJSON(selected,{style:{color:'#333',weight:7,opacity:.8,dashArray:dash}}).addTo(map);routeLayer=L.geoJSON(selected,{style:f=>({color:treeColor(f.properties.ai_tree_cover_01),weight:4,dashArray:dash}),onEachFeature:(f,l)=>l.bindTooltip(esc(f.properties.zip)+': '+esc(f.properties.route)+'<br>Nearby predicted trees: '+number(100*f.properties.ai_tree_cover_01)+'%')}).addTo(map);}
document.getElementById('objective').onchange=e=>{routeMode=e.target.value;drawRoute();};
document.getElementById('theme').onchange=async e=>{mode=e.target.value;if(blockLayer)blockLayer.setStyle(blockStyle);if(mode==='paths'){if(!pathData)pathData=await unpack(PATHS);if(!pathLayer)pathLayer=L.geoJSON(pathData,{style:f=>({color:treeColor(f.properties.tree_fraction),weight:2,opacity:.9}),onEachFeature:(f,l)=>l.bindTooltip('Nearby predicted trees: '+number(f.properties.tree_fraction===null?null:100*f.properties.tree_fraction)+'%<br>Corridor image coverage: '+number(100*f.properties.coverage)+'%')});pathLayer.addTo(map);}else if(pathLayer)map.removeLayer(pathLayer);drawRoute();updateLegend();};
(async()=>{try{const data=await unpack(BLOCKS);blockLayer=L.geoJSON(data,{style:blockStyle,onEachFeature:(f,l)=>{const p=f.properties;l.bindPopup('<b>Block '+esc(p.id)+'</b><br>'+esc(p.address)+'<br>AI tree cover: '+number(p.cover)+'%<br>Provisional friction: '+number(p.friction)+'<br>Observed image coverage: '+number(100*p.coverage)+'%');}}).addTo(map);map.fitBounds(blockLayer.getBounds());const scope=await unpack(SCOPE);L.geoJSON(scope,{style:{color:'#333',weight:2,fill:false,interactive:false}}).addTo(map);scope.features.forEach(f=>L.marker([f.properties.lat,f.properties.lon],{interactive:false,icon:L.divIcon({className:'zip-label',html:'<span style="background:white;padding:3px;font-weight:bold;pointer-events:none">'+esc(f.properties.ZCTA5)+'</span>'})}).addTo(map));routeData=await unpack(ROUTES);const points=await unpack(POINTS);L.geoJSON(points,{pointToLayer:(f,ll)=>L.circleMarker(ll,{radius:5,color:'#111',fillColor:f.properties.role==='Start'?'white':'#111',fillOpacity:1}),onEachFeature:(f,l)=>l.bindTooltip(esc(f.properties.zip)+': '+esc(f.properties.role)+' — illustrative endpoint')}).addTo(map);document.getElementById('objective').value=routeMode;document.getElementById('theme').value=mode;await document.getElementById('theme').onchange({target:{value:mode}});}catch(e){document.getElementById('legend').innerText='Map could not load. Use a current browser with DecompressionStream support.';}})();
</script></body></html>'''
 for key,val in [('TILE_URL',tiles_url()),('ATTRIBUTION',ATTR),('BLOCKS',blocks_payload),('PATHS',paths_payload),('ROUTES',routes_payload),('POINTS',points_payload),('SCOPE',scope_payload),('HEAT_MIN',float(blocks.heat.min())),('HEAT_MAX',float(blocks.heat.max()))]:template=template.replace(key,json.dumps(val))
 template=template.replace('HEAT_RANGE',f'{blocks.heat.min():.1f}–{blocks.heat.max():.1f}')
 target=OUT/'full_scope_geoai_map.html'
 if target.exists() and not (OUT/'full_scope_geoai_map_full.html').exists():shutil.copy2(target,OUT/'full_scope_geoai_map_full.html')
 target.write_text(template)
 print('Compact full-scope viewer saved:',len(template),'characters. Display geometry simplified only; analysis values unchanged.')
 return target
if __name__=='__main__':main()
